def flatten_depth(lst, depth):
    if depth <= 0:
        return list(lst)
    current = list(lst)
    for _ in range(depth):
        new_current = []
        for item in current:
            if isinstance(item, list):
                new_current.extend(item)
            else:
                new_current.append(item)
        current = new_current
    return current
